select is(pg_temp.payload('393817a6-f4f6-5563-9b22-4614aa481ad9'::uuid), $expected${"title":"Principles of Business Administration I","body":"Foundation course covering business functions, marketing fundamentals, organizational structure, management concepts, business environment analysis, and contemporary issues in Nigerian business administration.","topics":[{"chapter":"1-2","description":"Business Functions and Organizational Structure"},{"chapter":"3-4","description":"Marketing Fundamentals and Segmentation"},{"chapter":"5-6","description":"Management Concepts and Principles"},{"chapter":"7-8","description":"Business Environment and Strategy"},{"chapter":"9-10","description":"Contemporary Issues and Change Management in Nigeria"},{"chapter":"11-12","description":"Business Ownership, Ethics, and Corporate Governance"}],"examFocus":["Definition of business functions","Organizational structure types and benefits","Market segmentation strategies","Management theories and applications","PESTLE analysis and business environment","Contemporary challenges in Nigerian business","Business ownership types and liability","Corporate governance principles (NCCG 2018)","Leadership theories and styles","Theory explanations and definitions"],"keyTakeaways":[{"title":"The True Purpose of Business Goes Beyond Profit","description":"While classical thinkers like Adam Smith viewed businesses narrowly as profit-maximizing machines, the modern view sees businesses as social institutions responsible for value creation, employment generation, and wealth distribution for all stakeholders."},{"title":"Management is Universal and Interconnected","description":"Wherever there are people and goals, management is required. The four core functions—Planning, Organising, Leading, and Controlling—are deeply interrelated. You cannot control what you have not planned. Success is measured by Effectiveness (doing the right things) and Efficiency (using the least resources)."},{"title":"Constantly Scan the Dynamic Business Environment","description":"No business operates in a vacuum. Always apply the PESTLE framework (Political, Economic, Sociocultural, Technological, Legal, Environmental) to analyze forces shaping your industry and adapt to opportunities and threats."},{"title":"The Reality of the Nigerian Business Context","description":"As managers in Nigeria, you will face infrastructure deficits, economic volatility (inflation, FX constraints), and security threats. You must act as an \"Organizational Stabiliser\" and Change Agent while managing cultural rigidity, employee burnout, and the skills gap."},{"title":"Organizations are Open Systems Requiring Integration","description":"Systems Theory views businesses as open systems that receive inputs, transform them, and produce outputs. Cross-functional integration is critical—Marketing, Operations, HR, and Finance must work together, not in silos."},{"title":"Understand Business Ownership and Liability","description":"A Sole Proprietorship carries unlimited personal liability—your personal assets can be seized to pay business debts. Incorporating as a company (like a PLC) creates a separate legal entity and provides limited liability protection."},{"title":"Ethics, Governance, and Responsible Leadership","description":"Management is a recognized profession requiring adherence to ethical codes like NIM's. Uphold the NCCG 2018 principles: Responsibility, Accountability, Transparency, and Fairness. Strive to be a Transformational or Servant Leader who guides with honesty and empathy."}]}$expected$::jsonb, 'BUA201: with the text it had');
